INSERT INTO isuumo.estate (id, thumbnail, name, latitude, longitude, address, rent, door_height, door_width, popularity, description, features) VALUES ('1', '/images/estate/6098baee73589ef5693ce2e73c30538ec07426b287337a7bf28635f27023fc59.png', '吉田ISUビルディング', '39.61778813321466' , '142.08736944633878', '群馬県福生市東神田10丁目4番2号 港南シャルム360', '138843', '173', '77', '691612', '又国内思想指導の方針としては、較もすれば党派的に陥る全体主義ではなくして、何処までも公明正大なる君民一体、万民翼賛の皇道でなければならない。', '防犯カメラ,敷地内ゴミ置場'), ('2', '/images/estate/a5790ed7dd01e6e22217b4e098eced29f2a2df995a2e289086f029a3a8e5982c.png', '高橋ISUビルディング', '34.73428573446485' , '135.5494491915887', '島根県川崎市宮前区羽折町5丁目16番3号 富久町アーバン326', '36234', '143', '193', '854841', 'けれどもまあ考えて見ますとふしぎではござんせんか、毎日毎日お目にかかって居る時は、別にこれぞと云って、御なつかしくもお話ししたいとも思いませんでしたのにねえ。', '即入居可'), ('3', '/images/estate/d6cb0ade7a4b66565508ec7ce141eb83ee413a08180f200fcf89e156e0ff91f8.png', 'ISUアパート 佐藤', '35.20861134120814' , '139.23466529745886', '青森県横浜市神奈川区竜泉32丁目19番13号', '41805', '108', '76', '122759', 'そのあとは、みかけは天を摩す巨木でありながら、まるで綿でもつめた蛇籠のように軽く、押せば他愛もなくぐらぐらっと揺れるのである。', ''), ('4', '/images/estate/ca4a281b2c1f89f398be3234e5a0acf367afff28e7b2a8683ed756e736331287.png', '中川ISUビルディング', '34.707816558443554' , '135.1277489433509', '北海道西東京市独鈷沢37丁目10番2号 クレスト元浅草928', '193326', '148', '104', '226698', 'まるで月世界の山脈か砂丘のような起伏、石筍、天井からの無数の乳房、それが、光をうけるとパッと雪のようにかがやく。', 'バイク置場あり,ワンルーム'), ('5', '/images/estate/85ffc5b4a599513008f597a05b87fa5508d18c940d1562dec164a604a0d6736f.png', 'ISUアパート 鈴木', '34.80868756675473' , '135.43786348826748', '大分県国立市台場28丁目9番8号 パレス柿木沢新田811', '160860', '95', '75', '912374', 'けれども、夕暮にさえなりますと、私の心に夕栄の雲の様に様々な色と姿の思い出が湧きます中の一つが、とうとう斯うやって、筆をとらせたのでございます。', '浴室乾燥機,メゾネット,シューズボックス'), ('6', '/images/estate/8e464910a220b86dd4c3f45ec6f587fc8d70c686db0ed8cbd0868e11117bfe76.png', 'ISUアパート 山本', '32.981412312581945' , '130.11618973146776', '兵庫県横浜市瀬谷区台東10丁目22番20号', '165824', '199', '177', '459295', '法水は何より先に、この婦人の精神的な深さと、総身から滲み出てくる、物々しいまでの圧力に打たれざるを得なかった。', 'シューズボックス,オートロック,メゾネット'), ('7', '/images/estate/b8870315e0f883dc8e4f4df4837939f838aa5fb0b0555347e4098076ebd2a6b7.png', '佐藤 ISUマンション', '35.46520100328143' , '139.61310871900318', '山梨県江東区外国府間28丁目3番4号', '193838', '75', '164', '387607', 'しかしその時、折竹は一つの石をじっと見詰め、じつにブラジル産にしては稀ともいいたい、その石の青色に気を奪われていた。', ''), ('8', '/images/estate/993a641e463ae8f8885c9df2412a698b9d11af4218e8c2748ede24054432de97.png', '中川ISUビルディング', '33.422752115507315' , '130.54105706408575', '千葉県昭島市戸塚町30丁目2番7号 竜泉アーバン750', '152731', '95', '124', '146990', '生物は、わずか数種の爬虫類がいるだけで、まったく、水掻きをつけ藻をかぶって現われる、水棲人の棲所というに適わしいのである。', 'DIY可,都市ガス'), ('9', '/images/estate/055d5b9f0439cb9f1b3276c428e324b0d3cbd69a8cd5029eb6ac720c020719fc.png', 'ISUガーデン 渡辺', '35.63440321299848' , '138.78320565606856', '東京都八街市戸山27丁目16番1号', '66024', '118', '42', '621207', 'パーティションの上から、半月まえにこのフロアにやってきた男が顔をのぞかせて、景気よくやりましょう、というように慶一を見た。', ''), ('10', '/images/estate/3b820e7ed4b4e9ed0124bc9677257aa4587e863960e33dbdaac5a4b895addf19.png', '小川 ISUビル', '34.53436102373023' , '136.91688905064066', '富山県長生郡白子町箭坪27丁目17番11号', '178133', '193', '84', '394213', '自分の良心の不徹底ゆゑに苦しかつた、そしてある瞬間はまた、そんなに苦しむ事が愚しいやうな、一寸笑つてやりたいやうな氣もした。', ''), ('11', '/images/estate/2af51046f5547cbd983ca291139300ae5b69f69c61a67d1c5e89236baf900f04.png', '高橋ISUビルディング', '39.53539886562512' , '141.44499077029283', '茨城県横浜市金沢区戸島40丁目10番5号 コート台場109', '99070', '115', '102', '919668', 'と云うのは、彼と友人の支倉検事の私宅が聖堂の付近にあるばかりでなく、実に、不気味な前駆があったからだ。', 'メゾネット,床下収納'), ('12', '/images/estate/47b03fa3a408b9bf617afa6f58fcfcbdd772cf4eaaef7548e892ba09086ee523.png', '伊藤ISUビルディング', '35.27566599263763' , '139.84051955807263', '徳島県白井市細野26丁目24番13号', '45512', '154', '159', '869706', '半月形をしたルーベンス眉や、唇の両端が釣り上ったいわゆる覆舟口などと云うのは、元来淫らな形とされている。', '敷地内ゴミ置場'), ('13', '/images/estate/a85fac4a06dd6615201e6f7ec04db82f0335d33959b38e4fab8b6fd589360a3d.png', 'ISU吉田レジデンス', '36.33788944380322' , '137.34931209280876', '石川県川崎市多摩区三筋42丁目20番13号 松が谷ハイツ106', '62066', '110', '121', '823836', 'が、その美しさもいわゆる俳優的な遊惰な媚色であって、どの線どの陰影の中にも、思索的な深みや数学的な正確なものが現われ出てはいない。', 'オートロック,IHコンロ'), ('14', '/images/estate/ccc7c3a9ba7ded8d8b35bf